public void processShouldWork() throws Exception {
    CopyRequest copyRequest = new CopyRequest(ImapCommand.anyStateCommand("Name"), new IdRange[] { new IdRange(4, 6) }, ImapConstants.INBOX_NAME, true, TAG);
