@Test
public void testUnsupportedRight() throws Exception {
    SetACLRequest setACLRequest = new SetACLRequest("TAG", ImapCommand.anyStateCommand("Name"), MAILBOX_NAME, USER_1, UNSUPPORTED_RIGHT);
    when(mailboxManager.hasRight(path, MailboxACL.Right.Lookup, mailboxSession)).thenReturn(false);
    subject.doProcess(setACLRequest, responder, imapSession);
    verify(responder, times(1)).respond(argumentCaptor.capture());
    verifyNoMoreInteractions(responder);
    assertThat(argumentCaptor.getAllValues()).hasSize(1);
    assertThat(argumentCaptor.getAllValues().get(0)).matches(StatusResponseTypeMatcher.BAD_RESPONSE_MATCHER::matches);
}

@Test
public void testNoAdminRight() throws Exception {
    when(mailboxManager.hasRight(path, MailboxACL.Right.Lookup, mailboxSession)).thenReturn(true);
    when(mailboxManager.hasRight(path, MailboxACL.Right.Administer, mailboxSession)).thenReturn(false);
    subject.doProcess(replaceAclRequest, responder, imapSession);
    verify(responder, times(1)).respond(argumentCaptor.capture());
    verifyNoMoreInteractions(responder);
    assertThat(argumentCaptor.getAllValues()).hasSize(1);
    assertThat(argumentCaptor.getAllValues().get(0)).matches(StatusResponseTypeMatcher.NO_RESPONSE_MATCHER::matches);
}

@Test
public void testInexistentMailboxName() throws Exception {
    when(mailboxManager.getMailbox(any(MailboxPath.class), any(MailboxSession.class))).thenThrow(new MailboxNotFoundException(""));
    subject.doProcess(replaceAclRequest, responder, imapSession);
    verify(responder, times(1)).respond(argumentCaptor.capture());
    verifyNoMoreInteractions(responder);
    assertThat(argumentCaptor.getAllValues()).hasSize(1);
    assertThat(argumentCaptor.getAllValues().get(0)).matches(StatusResponseTypeMatcher.NO_RESPONSE_MATCHER::matches);
}

private void testOp(String prefix, EditMode editMode) throws MailboxException {
    when(mailboxManager.hasRight(path, MailboxACL.Right.Lookup, mailboxSession)).thenReturn(true);
    when(mailboxManager.hasRight(path, MailboxACL.Right.Administer, mailboxSession)).thenReturn(true);
    SetACLRequest r = new SetACLRequest("TAG", ImapCommand.anyStateCommand("Name"), MAILBOX_NAME, USER_1, prefix + SET_RIGHTS);
    subject.doProcess(r, responder, imapSession);
    verify(mailboxManager).applyRightsCommand(path, MailboxACL.command().key(user1Key).rights(setRights).mode(editMode).build(), mailboxSession);
    verify(responder, times(1)).respond(argumentCaptor.capture());
    verifyNoMoreInteractions(responder);
    assertThat(argumentCaptor.getAllValues()).hasSize(1);
    assertThat(argumentCaptor.getAllValues().get(0)).matches(StatusResponseTypeMatcher.OK_RESPONSE_MATCHER::matches);
}

