    FakeMail mail = FakeMail.builder().sender(MailAddressFixture.OTHER_AT_JAMES).recipients(MailAddressFixture.ANY_AT_JAMES, MailAddressFixture.ANY_AT_JAMES2).state("state").mimeMessage(MimeMessageBuilder.defaultMimeMessage()).build();
