private void createServer(MailboxManager mailboxManager) throws Exception {
    usersRepository = mock(UsersRepository.class);
    when(usersRepository.contains(USERNAME)).thenReturn(true);
    webAdminServer = WebAdminUtils.createWebAdminServer(new DefaultMetricFactory(), new UserMailboxesRoutes(new UserMailboxesService(mailboxManager, usersRepository), new JsonTransformer()));
    webAdminServer.configure(NO_CONFIGURATION);
    webAdminServer.await();
    RestAssured.requestSpecification = new RequestSpecBuilder().setContentType(ContentType.JSON).setAccept(ContentType.JSON).setBasePath(USERS_BASE + SEPARATOR + USERNAME + SEPARATOR + UserMailboxesRoutes.MAILBOXES).setPort(webAdminServer.getPort().toInt()).setConfig(newConfig().encoderConfig(encoderConfig().defaultContentCharset(Charsets.UTF_8))).build();
}

